/** Recorded sound effects (Kenney "Impact Sounds" and "Interface Sounds", CC0 1.0: free for commercial use, no credit
 * needed; see docs/third-party-licenses.md). Mono 16-bit PCM at 22050 Hz, trimmed, peak 0.5 (as the made-up sounds), as
 * base64, so the website and the phone's own engine (Hermes: no audio decoder) play them the same way. */
export const SFX_REC_RATE = 22050;
export const SFX_REC: Record<string, { name: string; b64: string }> = {
  punch: { name: "Punch", b64: "" },
  hit: { name: "Hit", b64: "" },
  metal: { name: "Metal hit", b64: "" },
  glass: { name: "Glass", b64: "" },
  bell: { name: "Bell", b64: "" },
  knock: { name: "Knock", b64: "" },
  thud: { name: "Thud", b64: "" },
  plate: { name: "Plate", b64: "" },
  step: { name: "Footstep", b64: "" },
  tap: { name: "Tap", b64: "" },
  select: { name: "Select", b64: "" },
  pluck: { name: "Pluck", b64: "" },
  bong: { name: "Bong", b64: "" },
  scratch: { name: "Scratch", b64: "" },
  success: { name: "Success", b64: "" },
  error: { name: "Error", b64: "" },
  switch: { name: "Switch", b64: "" },
  popup: { name: "Pop up", b64: "" },
};
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function bytesOf(s: string): Uint8Array {
  const out = new Uint8Array(Math.floor((s.length * 3) / 4) - (s.endsWith("==") ? 2 : s.endsWith("=") ? 1 : 0));
  let o = 0;
  for (let i = 0; i < s.length; i += 4) {
    const n = (B64.indexOf(s[i]) << 18) | (B64.indexOf(s[i + 1]) << 12) | ((B64.indexOf(s[i + 2]) & 63) << 6) | (B64.indexOf(s[i + 3]) & 63);
    if (o < out.length) out[o++] = (n >> 16) & 255; if (o < out.length) out[o++] = (n >> 8) & 255; if (o < out.length) out[o++] = n & 255;
  }
  return out;
}
const made = new Map<string, Float32Array>();
/** a recorded sound at sample rate `sr` (linear resampling), kept once per rate; null when it is not a recorded one */
export function sfxRecorded(kind: string, sr: number): Float32Array | null {
  const r = Object.prototype.hasOwnProperty.call(SFX_REC, kind) ? SFX_REC[kind] : null; if (!r) return null;
  const key = kind + "|" + sr, had = made.get(key); if (had) return had;
  const b = bytesOf(r.b64), n = b.length >> 1, src = new Float32Array(n);
  for (let i = 0; i < n; i++) { const v = b[2 * i] | (b[2 * i + 1] << 8); src[i] = (v > 32767 ? v - 65536 : v) / 32767; }
  const k = SFX_REC_RATE / sr, len = Math.max(1, Math.floor(n / k)), y = new Float32Array(len);
  for (let i = 0; i < len; i++) { const x = i * k, j = Math.floor(x), f = x - j; y[i] = (src[j] ?? 0) * (1 - f) + (src[j + 1] ?? src[j] ?? 0) * f; }
  made.set(key, y); return y;
}
